    /* ── Setup: Despliegue y actualización del engine ── */
    "setup.deploy.title": "Despliegue y actualización del engine",
    "setup.deploy.body": "El comprador no necesita Rojo ni Argon. La configuración se hace directamente en Studio (doble clic en el ModuleScript).",
    "setup.deploy.h4fresh": "Primera vez (instalación nueva)",
    "setup.deploy.fresh1": "Abre Roblox Studio → tu place (o uno nuevo)",
    "setup.deploy.fresh2": "<strong>Home → Insert from File</strong> → elige <code>ClubKit.rbxm</code> (nombre del archivo de Hazastudio)",
    "setup.deploy.fresh3": "Asegúrate de que la estructura del kit aparezca en el Explorer: consulta el <a href=\"#files\">mapa de rutas</a>",
    "setup.deploy.fresh4": "Edita <code>ClubKitConfig</code> + <code>Secrets</code> (branding, group, shop, donation)",
    "setup.deploy.fresh5": "Prueba → <strong>File → Publish to Roblox</strong>",
    "setup.deploy.h4update": "Actualización del engine (método principal: sincronización de fuentes)",
    "setup.deploy.updatelead": "Para actualizar solo los scripts del engine Luau (sin reenviar toda la GUI/tableros):",
    "setup.deploy.update1": "Instala / abre el plugin <strong>Hazastudio Club Kit</strong> en Studio",
    "setup.deploy.update2": "(Si se solicita) primero <strong>Settings → Update plugin</strong>",
    "setup.deploy.update3": "<strong>Engine → Update Engine</strong> → espera el éxito → <strong>Save place</strong>",
    "setup.deploy.card1.title": "Lo que no se reemplaza",
    "setup.deploy.card1.p1": "<code>ClubKitConfig</code> y <code>Secrets</code> <strong>no</strong> se reemplazan por completo. Tras Update Engine, el plugin <strong>completa</strong> las claves de configuración que falten (aditivo) desde el schema; los valores existentes del comprador se conservan. El runtime también completa en memoria mediante <code>ConfigBootstrap</code>.",
    "setup.deploy.card1.p2": "StarterGui, los tableros del Workspace y los assets de ServerStorage <strong>no</strong> participan en la sincronización de fuentes: se despliegan manualmente / con RBXM si cambian.",
    "setup.deploy.h4rbxm": "Actualización completa mediante rbxm (poco frecuente)",
    "setup.deploy.rbxm1": "Respalda el contenido de <code>ClubKitConfig</code> + <code>Secrets</code>",
    "setup.deploy.rbxm2": "Elimina las carpetas del engine <code>Hazastudio_ClubKit</code> en ReplicatedStorage / ServerScriptService / StarterPlayerScripts / ReplicatedFirst; <strong>no elimines</strong> <code>Hazastudio_ClubKitConfig</code> / <code>Hazastudio_ClubKitSecrets</code>",
    "setup.deploy.rbxm3": "Inserta la nueva versión del rbxm",
    "setup.deploy.rbxm4": "Comprueba que la configuración del comprador siga ahí; restáurala desde el backup si fue sobrescrita",
    "setup.deploy.card2.title": "1 place = 1 config",
    "setup.deploy.card2.body": "Cada place tiene su propio <code>ClubKitConfig</code>. Duplica el place en Studio si quieres un venue distinto.",

    /* ── Setup: Solución de problemas ── */
    "setup.trouble.title": "Solución de problemas",
    "setup.trouble.lead": "Problemas comunes al configurar y desplegar Club Kit.",
    "setup.trouble.a1": "Completa <code>GroupId</code> en <code>ReplicatedStorage/Hazastudio_ClubKitConfig/ClubKitConfig</code> o activa el showcase.",
    "setup.trouble.a2": "Completa <code>ApiUrl</code> o usa el showcase.",
    "setup.trouble.q3": "Advertencia de tienda BuyGamePassId <code>0</code>",
    "setup.trouble.a3": "Completa <code>BuyGamePassId</code> + <code>GiftId</code> en <code>Shop.Products</code> desde el Creator Dashboard (Game Pass + Dev Product de regalo).",
    "setup.trouble.a4": "Crea un Developer Product de difusión en el Creator Dashboard → completa <code>PaidBroadcast.ProductId</code> en <code>ClubKitConfig</code>. Ver <a href=\"#paid-broadcast\">Difusión pagada</a>.",
    "setup.trouble.q5": "El Broadcast de la barra superior no muestra el aviso / el pago falla",
    "setup.trouble.a5": "Comprueba que el <code>ProductId</code> sea correcto, que el producto esté activo en el dashboard y que el precio en Robux esté definido. Los recibos se procesan por el mismo pipeline de la tienda que la membresía.",
    "setup.trouble.q6": "Saweria / efectivo \"API not configured\"",
    "setup.trouble.a6": "Completa <code>ApiUrl</code> + <code>DonationApiSecret</code>; verifica que <code>DonationCash</code> esté activo y que <code>Provider</code> sea correcto (<code>bagibagi</code> / <code>saweria</code> / <code>sociabuzz</code>).",
    "setup.trouble.q7": "Robux/Likes \"No … yet\"",
    "setup.trouble.a7": "Normal: aún no hay datos; o usa el <a href=\"#leaderboard-seeder\">seeder de un solo uso</a>.",
    "setup.trouble.q8": "Quiero llenar las clasificaciones manualmente para probar",
    "setup.trouble.a8": "Usa <code>/addcash</code> o <code>/setrobux</code> (owner): esos sí persisten. <code>/fakecash</code> / <code>/fakerobux</code> (o los alias <code>/test*</code>) solo son vista previa de VFX/notificación.",
    "setup.trouble.q9": "Update Engine / CONFIG MERGE FAILED",
    "setup.trouble.a9": "Revisa la consola del plugin. Una fusión aditiva fallida significa que las claves nuevas no se escribieron en el Source; no asumas que las nuevas Features existen hasta que la fusión sea correcta. Config y Secrets nunca se reemplazan por completo.",
    "setup.trouble.q10": "La pestaña de efectivo sigue visible pese a estar desactivada",
    "setup.trouble.a10": "<code>Cash.Enabled = false</code> + reingresar; la pestaña IDR se oculta en el cliente.",
    "setup.trouble.q11": "No aparece el World VFX / falta World Effects en Settings",
    "setup.trouble.a11": "Revisa <code>Features.DonationWorldEffects</code>. Si es <code>false</code>, Nuke/Smite/BlackHole están desactivados, pero el aura permanece. El World VFX es solo para efectivo IDR, no para Robux.",
    "setup.trouble.q12": "El seeder no funciona",
    "setup.trouble.a12": "<code>ENABLED = true</code>, API Services activado; revisa los nombres de carpeta del ModuleScript.",
    "setup.trouble.q13": "Tablero en blanco sin texto",
    "setup.trouble.a13": "Agrega <code>LoadingOverlay</code> a la plantilla SurfaceGui del place.",
    "setup.trouble.q14": "Products Not Found (Robux)",
    "setup.trouble.a14": "Crea Developer Products o completa <code>RobuxProducts</code>.",
    "setup.trouble.q15": "El rol no aparece",
    "setup.trouble.a15": "Revisa <code>enabled = true</code> y los alias de rol.",
    "setup.trouble.q16": "No se otorgan las herramientas",
    "setup.trouble.a16": "Revisa <code>ServerStorage/Tools/&lt;toolFolder&gt;</code>.",
    "setup.trouble.q17": "Comando de owner rechazado",
    "setup.trouble.a17": "Completa <code>OwnerUserId</code> o usa el rango de grupo 255.",
    "setup.trouble.q18": "Advertencia de secreto vacío",
    "setup.trouble.a18": "Completa <code>ServerScriptService/Hazastudio_ClubKitSecrets/Secrets</code> o deja vacío <code>ApiUrl</code>.",

