    /* ── Updates ── */
    "meta.updates.title": "Updates — Hazastudio Clubkit",
    "meta.updates.description": "Notas de versión de Club Kit, pasos de Update Engine y guías de upgrade.",
    "updates.kicker": "Notas de versión",
    "updates.version": "Actual 2.4.72",
    "updates.title": "Updates",
    "updates.lead": "Cómo obtener el engine más reciente, destacados orientados al comprador y enlaces de upgrade por versión. La fuente de verdad completa sigue en <code>CHANGELOG.md</code> + la carpeta <code>docs/releases/</code>.",
    "updates.how.title": "Update Engine (diario)",
    "updates.how.1": "Haz copia de seguridad / asegúrate de que <code>ClubKitConfig</code> y <code>Secrets</code> estén a salvo (el plugin no los reemplaza por completo).",
    "updates.how.2": "Studio → plugin Club Kit → pestaña <strong>Engine</strong> → <strong>Check Update</strong>.",
    "updates.how.3": "Ejecuta <strong>Update Engine</strong> y espera a que termine (fill-forward aditivo de config si hay claves nuevas).",
    "updates.how.4": "<strong>Guarda</strong> el place. Verifica que KitVersion (F9) = la versión de arriba.",
    "updates.how.note": "Instalación nueva o envío de modelos GUI/tablero → usa Packager / RBXM (poco frecuente). Detalle: <a href=\"setup.html#deploy\">Setup → Deploy</a>.",
    "updates.safe.title": "Lo que no se reemplaza",
    "updates.safe.1": "<code>Hazastudio_ClubKitConfig/ClubKitConfig.luau</code> — se conservan los valores del comprador; las claves nuevas se rellenan con defaults (fill-forward).",
    "updates.safe.2": "<code>Hazastudio_ClubKitSecrets/Secrets.luau</code> — no se toca.",
    "updates.safe.3": "Tableros StarterGui / modelos Workspace — solo sync del engine Luau; los assets visuales siguen desplegándose a mano si cambian.",
    "updates.whatsNew": "What's new",
    "updates.whatsLead": "Resumen orientado al comprador. Abre un ítem para el detalle. Changelog completo: <a href=\"../CHANGELOG.md\">CHANGELOG.md</a>.",
    "updates.cat.security": "Security",
    "updates.v72.blurb": "Patch de auditoría — correcciones de pérdida de datos en DataStore, boot más resistente, cierre de 3 brechas de abuso.",
    "updates.v72.f1": "Favorites, stickers y XP de nivel podían perderse si el save fallaba justo al desconectarse el jugador — ahora se reintenta automáticamente en vez de descartarse.",
    "updates.v72.f2": "El cliente podía colgarse en el boot (loading screen atascada) si faltaba un remote o carpeta GUI — ahora expira y desactiva solo esa función (soft-disable).",
    "updates.v72.f3": "El panel de Dance en teléfonos sin el wrapper móvil ahora usa el layout de escritorio en vez de romper todo el dance sync.",
    "updates.v72.f4": "HotbarInventoryService ya no acumula conexiones de personaje en cada respawn.",
    "updates.v72.s1": "El pool global de stickers y la resolución de tracks por asset ID ahora requieren admin/DJ — las subidas/solicitudes propias de jugadores normales siguen funcionando, solo no escriben en el estado compartido/global.",
    "updates.v72.s2": "CommandLibraryController ahora tiene una puerta de permisos central, así un comando futuro sin su propio check no queda abierto a todos por defecto.",
    "updates.v72.s3": "Las instalaciones nuevas ya no heredan el UserId del desarrollador del kit como admin por defecto en la plantilla de config.",
    "updates.v71.blurb": "Admin Hub, daily boards, UI motion, plugin Aurora Dusk, docs i18n.",
    "updates.v71.a1": "<strong>Admin Hub</strong> — opt-in <code>Features.AdminHub</code> (desactivado por defecto).",
    "updates.v71.a2": "<strong>Daily boards ×3</strong> — combined / Robux / cash; formato <code>RP </code>.",
    "updates.v71.a3": "<strong>UI motion</strong> — MotionPresets, PressFeedback, UISpring.",
    "updates.v71.a4": "<strong>Docs hub + i18n</strong> — Home/Setup/Updates · ID/EN/JA/ES.",
    "updates.v71.a5": "<strong>Plugin Aurora Dusk</strong> — panel Swiss-knife + escritura de Config + hot-reload.",
    "updates.v71.f1": "Botón Cinematic Dock del topbar oculto para no-admins.",
    "updates.v70.blurb": "Ajuste de versión: Check Update ve la etiqueta nueva.",
    "updates.cat.changed": "Changed",
    "updates.v70.1": "<strong>Ajuste de versión</strong> — sin delta de funciones vs 2.4.69; bump para que Studio Check Update tome una etiqueta reciente.",
    "updates.upgradeGuide": "Guía de upgrade",
